func chatDisplayText(e views.EventSummary) string {
	if e.TextContent != "" {
		return e.TextContent
	}
	return e.TextPreview
}

func reasoningPreview(text string) string {
	if len(text) <= 80 {
		return text
	}
	return text[:80] + "..."
}

